parameters.jsCode:
const raw = items[0].json.output; // ou de onde vier o texto
if (typeof raw !== 'string') throw new Error("Esperava string");

const parts = raw
  .split(/\r?\n/)
  .map(s => s.trim())
  .filter(s => s !== "");

return parts.map(p => ({ json: { text: p, numero: items[0].json.numero } }));
